-- ════════════════════════════════════════════════════════════════════════════
-- Slugs are generated by BEFORE INSERT triggers when none is supplied
-- (private.businesses_before_write / private.catalogue_items_before_write treat
-- NULL and '' the same). Declaring an empty default makes that explicit in the
-- schema, so the API (and `supabase gen types`) treats slug as optional on
-- insert. The triggers always replace '' before the CHECK constraints run.
-- ════════════════════════════════════════════════════════════════════════════

alter table public.businesses alter column slug set default '';
alter table public.catalogue_items alter column slug set default '';
